from pathlib import Path

p = Path('public/summertime-crmdemo/index.html')
s = p.read_text()

if 'id="dtex-gainsight-p1-script"' in s:
    print('DTEX Gainsight/P1 patch already present')
    raise SystemExit(0)

nav_old = '<button data-view="playbooks">Playbook Library</button></nav>'
nav_new = '<button data-view="playbooks">Playbook Library</button><button data-view="healthsettings">Health Settings</button></nav>'
if nav_old not in s:
    raise SystemExit('DTEX nav marker not found')
s = s.replace(nav_old, nav_new, 1)

playbooks = '<section id="playbooks" class="view"><div class="playbook-grid" id="playbook-grid"></div></section>'
settings_section = '''<section id="healthsettings" class="view"><article class="card"><div class="card-head"><div><h2>Customer Health Settings</h2><p>Transparent, adjustable weighting and thresholds for this independent DTEX interview prototype.</p></div><span class="pill lime">Calculated</span></div><div class="card-body" id="dtex-health-settings-body"></div></article></section>'''
if playbooks not in s:
    raise SystemExit('DTEX playbooks marker not found')
s = s.replace(playbooks, playbooks + settings_section, 1)

extra_css = r'''<style id="dtex-gainsight-p1-css">
.dtex-health-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.dtex-health-thresholds{display:grid;grid-template-columns:repeat(2,minmax(0,220px));gap:10px;margin-top:12px}.dtex-health-note{padding:11px 12px;border:1px solid var(--line);border-left:3px solid var(--lime);border-radius:10px;background:var(--panel2);font-size:9px;line-height:1.55;color:var(--muted);margin-bottom:12px}.dtex-health-total{font-size:11px;font-weight:900;margin:10px 0}.dtex-health-error{min-height:16px;color:var(--red);font-size:9px;margin-top:7px}.dtex-editor{margin-top:13px;padding-top:12px;border-top:1px solid var(--line)}.dtex-editor h4{font-size:10px;margin:0 0 8px}.dtex-editor-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:9px}.dtex-goal-manager{display:grid;gap:7px;margin-top:12px}.dtex-manage-row{display:flex;justify-content:space-between;gap:8px;padding:8px;border:1px solid var(--line);border-radius:9px;background:var(--panel2);font-size:8px}.dtex-manage-actions{display:flex;gap:5px;align-items:flex-start}.dtex-manage-actions button{padding:4px 6px}.dtex-save-status{font-size:9px;color:var(--good);min-height:14px;margin-top:6px}
@media(max-width:800px){.dtex-health-grid{grid-template-columns:1fr 1fr}}@media(max-width:520px){.dtex-health-grid,.dtex-health-thresholds{grid-template-columns:1fr}}
</style>'''
s = s.replace('</head>', extra_css + '\n</head>', 1)

overlay = r'''<script id="dtex-gainsight-p1-script">
(function(){
'use strict';
const DTEX_HEALTH_KEY='dtex_health_settings_v2',DTEX_OVERRIDE_KEY='dtex_account_overrides_v2';
const DTEX_HEALTH_DEFAULTS={adoption:20,value:20,relationship:15,technical:25,supportRisk:10,successPlan:10};
const DTEX_HEALTH_THRESHOLDS={healthy:80,watch:65};
const dtexClamp=v=>Math.max(0,Math.min(100,Math.round(Number(v)||0)));
function dtexRead(k,fallback){try{return Object.assign({},fallback,JSON.parse(localStorage.getItem(k)||'{}'))}catch(e){return {...fallback}}}
let dtexHealthSettings={weights:dtexRead(DTEX_HEALTH_KEY,{}).weights||{...DTEX_HEALTH_DEFAULTS},thresholds:dtexRead(DTEX_HEALTH_KEY,{}).thresholds||{...DTEX_HEALTH_THRESHOLDS}};
dtexHealthSettings.weights=Object.assign({},DTEX_HEALTH_DEFAULTS,dtexHealthSettings.weights||{});dtexHealthSettings.thresholds=Object.assign({},DTEX_HEALTH_THRESHOLDS,dtexHealthSettings.thresholds||{});
let dtexOverrides={};try{dtexOverrides=JSON.parse(localStorage.getItem(DTEX_OVERRIDE_KEY)||'{}')}catch(e){}
function dtexStoreSettings(){localStorage.setItem(DTEX_HEALTH_KEY,JSON.stringify(dtexHealthSettings))}
function dtexStoreOverride(a,keys){const o=dtexOverrides[a.id]=dtexOverrides[a.id]||{};for(const k of keys)o[k]=JSON.parse(JSON.stringify(a[k]));localStorage.setItem(DTEX_OVERRIDE_KEY,JSON.stringify(dtexOverrides))}
for(const a of accounts){if(dtexOverrides[a.id])Object.assign(a,dtexOverrides[a.id])}
function dtexMeetingRecency(a){const ms=allMeetings(a).filter(m=>m.date).sort((x,y)=>String(y.date).localeCompare(String(x.date)));if(!ms.length)return 35;const days=Math.max(0,Math.ceil((Date.now()-new Date(ms[0].date+'T12:00:00').getTime())/86400000));return days<=30?100:days<=60?85:days<=90?70:days<=120?55:40}
function dtexRelationship(a){const quality=dtexClamp(a.stakeholder),recency=dtexMeetingRecency(a),exec=allPeople(a).some(p=>/executive sponsor|ciso|security vp/i.test((p.role||'')+' '+(p.lane||'')))?100:40;return dtexClamp(quality*.60+recency*.25+exec*.15)}
function dtexSupportRisk(a){const sev=String(a.supportSev||'None').toLowerCase(),penalty=sev.includes('sev 1')?25:sev.includes('sev 2')?15:sev.includes('sev 3')?7:sev.includes('sev 4')?3:0;return dtexClamp(dtexClamp(a.support)-penalty)}
function dtexSuccessPlan(a){const g=a.goals||[];return g.length?dtexClamp(g.reduce((sum,x)=>sum+dtexClamp(x.progress),0)/g.length):50}
function dtexSignals(a){return{adoption:dtexClamp(a.adoption),value:dtexClamp(a.value),relationship:dtexRelationship(a),technical:dtexClamp(a.coverage),supportRisk:dtexSupportRisk(a),successPlan:dtexSuccessPlan(a)}}
function dtexScore(a){const w=dtexHealthSettings.weights,sig=dtexSignals(a),total=Object.values(w).reduce((x,y)=>x+Number(y||0),0)||100;return dtexClamp(Object.keys(DTEX_HEALTH_DEFAULTS).reduce((sum,k)=>sum+sig[k]*Number(w[k]||0),0)/total)}
function dtexRecalc(){for(const a of accounts){a.health=dtexScore(a);a.type=healthType(a.health)}}
healthType=function(v){const t=dtexHealthSettings.thresholds;return Number(v)>=Number(t.healthy)?'good':Number(v)>=Number(t.watch)?'warn':'bad'};
flags=function(a){const f=[],t=dtexHealthSettings.thresholds,sig=dtexSignals(a);if(a.health<Number(t.watch))f.push('Health <'+t.watch);for(const [k,label] of [['adoption','Adoption'],['value','Value'],['relationship','Relationship'],['technical','Technical'],['supportRisk','Support / risk'],['successPlan','Success plan']])if(sig[k]<70)f.push(label+' <70%');if(a.commercial<70)f.push('Commercial readiness <70%');if(a.renewalDays<=90)f.push('Renewal ≤90d');return f};
dtexRecalc();
function dtexHealthWeightField(label,key,help){return `<div class="field"><span>${label} weight %</span><input class="dtex-health-weight" data-health-key="${key}" type="number" min="0" max="100" step="1" value="${dtexHealthSettings.weights[key]}" style="width:100%;margin-top:6px"><p>${help}</p></div>`}
function dtexRenderSettings(){const box=document.getElementById('dtex-health-settings-body');if(!box)return;const w=dtexHealthSettings.weights,t=dtexHealthSettings.thresholds,total=Object.values(w).reduce((x,y)=>x+Number(y||0),0);box.innerHTML=`<div class="dtex-health-note"><strong>Model basis:</strong> Defaulted to Gainsight-style Customer Success health practices except where overridden by DTEX priorities. DTEX overrides increase <strong>Technical / program coverage</strong> and <strong>Success-plan execution</strong> to reflect proactive insider-risk program maturity, operational coverage, and measurable outcome execution. This is an independent prototype interpretation, not a DTEX internal scorecard.</div><div class="dtex-health-grid">${dtexHealthWeightField('Adoption','adoption','Workflow adoption and program use.')}${dtexHealthWeightField('Value realization','value','Documented outcome and ROI evidence.')}${dtexHealthWeightField('Relationship & engagement','relationship','Stakeholder quality, meeting recency and executive coverage.')}${dtexHealthWeightField('Technical / program coverage','technical','Telemetry / technical coverage and program readiness.')}${dtexHealthWeightField('Support / risk','supportRisk','Support confidence adjusted for active severity.')}${dtexHealthWeightField('Success-plan execution','successPlan','Progress across documented success-plan objectives.')}</div><div class="dtex-health-total">Weight total: <span id="dtex-health-total">${total}</span>% <span style="color:var(--muted)">(must equal 100%)</span></div><div class="dtex-health-thresholds"><div class="field"><span>Healthy starts at</span><input id="dtex-healthy-threshold" type="number" min="1" max="100" value="${t.healthy}" style="width:100%;margin-top:6px"></div><div class="field"><span>Watch starts at</span><input id="dtex-watch-threshold" type="number" min="0" max="99" value="${t.watch}" style="width:100%;margin-top:6px"></div></div><div id="dtex-health-error" class="dtex-health-error"></div><div class="dtex-editor-actions"><button class="btn primary" id="dtex-save-health">Save health model</button><button class="btn" id="dtex-reset-health">Reset DTEX recommended weights</button></div><div style="font-size:8px;line-height:1.55;color:var(--muted);margin-top:10px"><strong>Formula:</strong> weighted average of the six dimensions above. Relationship & engagement = 60% stakeholder-quality score + 25% meeting recency + 15% executive coverage. Support / risk = support confidence minus the active support-severity penalty. Commercial readiness and renewal timing remain separate readiness signals rather than inputs to Health.</div>`}
renderHealth=function(){const w=dtexHealthSettings.weights,s=[['Adoption / workflow depth','adoption'],['Outcome realization','value'],['Relationship & engagement','relationship'],['Technical / program coverage','technical'],['Support / risk','supportRisk'],['Success-plan execution','successPlan']];document.getElementById('health-model').innerHTML=s.map(([n,k])=>`<div class="meter"><div class="meter-top"><b>${n}</b><span>${w[k]}% weight</span></div><div class="bar"><i style="width:${Math.min(100,w[k]*3.2)}%"></i></div></div>`).join('')+'<p style="font-size:8px;line-height:1.55;color:var(--muted)">Defaulted to Gainsight-style health practices except where DTEX priorities override the weighting. Commercial readiness and renewal timing are separate from Health.</p>'};
function dtexRefresh(){dtexRecalc();renderKpis();renderWatch();renderBars();renderMoments();renderAccounts();renderSuccess();renderMatrix();renderHealth();renderMeetings();renderRenewals();renderSupport();dtexRenderSettings()}
function dtexPageView(id){if(typeof gtag==='function')gtag('event','page_view',{page_title:'DTEX CS '+id,page_location:location.href,page_path:'/dtex/'+id,demo_name:'dtex_customer_success_measurement'})}
navigate=function(id){document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));const t={command:'Portfolio Command Center',accounts:'Accounts',success:'Success Plans',adoption:'Adoption & Value',meetings:'EBRs & Meetings',renewals:'Renewal Metrics',escalations:'Support & i³',playbooks:'Playbook Library',healthsettings:'Health Settings'};document.getElementById('page-title').textContent=t[id]||'Customer Success';sendEvent('crm_view_change',{view:id});dtexPageView(id)};
const dtexOriginalDrawer=renderDrawer;
renderDrawer=function(a){dtexOriginalDrawer(a);const sections=[...document.querySelectorAll('#drawer-body details.section')],find=n=>sections.find(x=>(x.querySelector('summary')?.textContent||'').includes(n));const tech=find('Technical lifecycle'),commercial=find('Commercial record'),success=find('Success plan');if(tech){tech.querySelector('.section-content').insertAdjacentHTML('beforeend',`<div class="dtex-editor"><h4>Edit Technical / Program context</h4><div class="form-grid"><input id="dtex-t-coverage" type="number" min="0" max="100" value="${a.coverage}" placeholder="Coverage %"><input id="dtex-t-support" type="number" min="0" max="100" value="${a.support}" placeholder="Support confidence %"><input id="dtex-t-sev" value="${esc(a.supportSev)}" placeholder="Support severity"><input id="dtex-t-tsm" value="${esc(a.tsm)}" placeholder="Technical Success owner"><input id="dtex-t-i3" class="wide" value="${esc(a.i3Status)}" placeholder="i³ status"><input id="dtex-t-integrations" class="wide" value="${esc((a.integrations||[]).join(', '))}" placeholder="Integrations"><input id="dtex-t-modules" class="wide" value="${esc((a.modules||[]).join(', '))}" placeholder="Active areas"><button class="btn primary wide" data-save-dtex-technical="${a.id}">Save technical context</button></div><div class="dtex-save-status" id="dtex-technical-status"></div></div>`)}if(commercial){commercial.querySelector('.section-content').insertAdjacentHTML('beforeend',`<div class="dtex-editor"><h4>Edit Adoption, Value & Commercial context</h4><div class="form-grid"><input id="dtex-c-arr" type="number" value="${a.arr}" placeholder="ARR"><input id="dtex-c-renewal" type="number" min="0" value="${a.renewalDays}" placeholder="Renewal days"><input id="dtex-c-adoption" type="number" min="0" max="100" value="${a.adoption}" placeholder="Adoption %"><input id="dtex-c-value" type="number" min="0" max="100" value="${a.value}" placeholder="Value evidence %"><input id="dtex-c-stakeholder" type="number" min="0" max="100" value="${a.stakeholder}" placeholder="Relationship quality %"><input id="dtex-c-commercial" type="number" min="0" max="100" value="${a.commercial}" placeholder="Commercial readiness %"><input id="dtex-c-ae" class="wide" value="${esc(a.ae)}" placeholder="Account Executive"><button class="btn primary wide" data-save-dtex-commercial="${a.id}">Save adoption / value / commercial context</button></div><div style="font-size:8px;color:var(--muted);margin-top:6px">Adoption, value and relationship quality feed Health. Commercial readiness and renewal timing do not.</div></div>`)}if(success){success.querySelector('.section-content').insertAdjacentHTML('beforeend',`<div class="dtex-editor"><h4>Manage success-plan objectives</h4><div class="dtex-goal-manager">${(a.goals||[]).map((g,i)=>`<div class="dtex-manage-row"><div><b>${esc(g.name)}</b><br><span>${g.progress}% · ${esc(g.owner)}</span></div><div class="dtex-manage-actions"><button class="btn" data-edit-dtex-goal="${a.id}:${i}">Edit</button><button class="btn" data-del-dtex-goal="${a.id}:${i}">Remove</button></div></div>`).join('')}</div><input id="dtex-goal-index" type="hidden"><div class="form-grid"><input id="dtex-goal-name" class="wide" placeholder="Objective"><input id="dtex-goal-progress" type="number" min="0" max="100" value="50" placeholder="Progress %"><input id="dtex-goal-owner" placeholder="Owner"><input id="dtex-goal-proof" class="wide" placeholder="Proof definition"><button class="btn primary wide" data-save-dtex-goal="${a.id}">Add / save objective</button></div></div>`)}}
function dtexAccountById(id){return accounts.find(a=>String(a.id)===String(id))}
function dtexVal(id){return document.getElementById(id)?.value??''}
const dtexOriginalBind=bind;
bind=function(){dtexOriginalBind();dtexRenderSettings();document.querySelectorAll('.dtex-health-weight').forEach(x=>x.oninput=()=>{const total=[...document.querySelectorAll('.dtex-health-weight')].reduce((sum,z)=>sum+Number(z.value||0),0);const e=document.getElementById('dtex-health-total');if(e)e.textContent=total});document.getElementById('dtex-save-health')?.addEventListener('click',()=>{const next={};document.querySelectorAll('.dtex-health-weight').forEach(x=>next[x.dataset.healthKey]=Number(x.value||0));const total=Object.values(next).reduce((x,y)=>x+y,0),healthy=Number(dtexVal('dtex-healthy-threshold')),watch=Number(dtexVal('dtex-watch-threshold')),err=document.getElementById('dtex-health-error');if(total!==100){err.textContent=`Weights must total 100%. Current total: ${total}%.`;return}if(!(healthy>watch&&healthy<=100&&watch>=0)){err.textContent='Healthy threshold must be greater than Watch threshold.';return}dtexHealthSettings={weights:next,thresholds:{healthy,watch}};dtexStoreSettings();dtexRefresh();sendEvent('health_model_saved',{model:'gainsight_default_dtex_override'})});document.getElementById('dtex-reset-health')?.addEventListener('click',()=>{dtexHealthSettings={weights:{...DTEX_HEALTH_DEFAULTS},thresholds:{...DTEX_HEALTH_THRESHOLDS}};dtexStoreSettings();dtexRefresh()});dtexPageView('command')};
document.addEventListener('click',e=>{const saveT=e.target.closest?.('[data-save-dtex-technical]');if(saveT){const a=dtexAccountById(saveT.dataset.saveDtexTechnical);Object.assign(a,{coverage:dtexClamp(dtexVal('dtex-t-coverage')),support:dtexClamp(dtexVal('dtex-t-support')),supportSev:dtexVal('dtex-t-sev'),tsm:dtexVal('dtex-t-tsm'),i3Status:dtexVal('dtex-t-i3'),integrations:dtexVal('dtex-t-integrations').split(',').map(x=>x.trim()).filter(Boolean),modules:dtexVal('dtex-t-modules').split(',').map(x=>x.trim()).filter(Boolean)});dtexStoreOverride(a,['coverage','support','supportSev','tsm','i3Status','integrations','modules']);dtexRecalc();renderDrawer(a);renderKpis();renderWatch();renderBars();renderSupport();return}const saveC=e.target.closest?.('[data-save-dtex-commercial]');if(saveC){const a=dtexAccountById(saveC.dataset.saveDtexCommercial);Object.assign(a,{arr:Number(dtexVal('dtex-c-arr'))||0,renewalDays:Math.max(0,Number(dtexVal('dtex-c-renewal'))||0),adoption:dtexClamp(dtexVal('dtex-c-adoption')),value:dtexClamp(dtexVal('dtex-c-value')),stakeholder:dtexClamp(dtexVal('dtex-c-stakeholder')),commercial:dtexClamp(dtexVal('dtex-c-commercial')),ae:dtexVal('dtex-c-ae')});a.end=daysFromNow(a.renewalDays);dtexStoreOverride(a,['arr','renewalDays','end','adoption','value','stakeholder','commercial','ae']);dtexRecalc();renderDrawer(a);dtexRefresh();return}const editG=e.target.closest?.('[data-edit-dtex-goal]');if(editG){const[id,idx]=editG.dataset.editDtexGoal.split(':'),a=dtexAccountById(id),g=a.goals[Number(idx)];document.getElementById('dtex-goal-index').value=idx;document.getElementById('dtex-goal-name').value=g.name;document.getElementById('dtex-goal-progress').value=g.progress;document.getElementById('dtex-goal-owner').value=g.owner;document.getElementById('dtex-goal-proof').value=g.proof;return}const delG=e.target.closest?.('[data-del-dtex-goal]');if(delG){const[id,idx]=delG.dataset.delDtexGoal.split(':'),a=dtexAccountById(id);a.goals.splice(Number(idx),1);dtexStoreOverride(a,['goals']);dtexRecalc();renderDrawer(a);dtexRefresh();return}const saveG=e.target.closest?.('[data-save-dtex-goal]');if(saveG){const a=dtexAccountById(saveG.dataset.saveDtexGoal),idx=dtexVal('dtex-goal-index'),g={name:dtexVal('dtex-goal-name').trim(),progress:dtexClamp(dtexVal('dtex-goal-progress')),owner:dtexVal('dtex-goal-owner').trim(),proof:dtexVal('dtex-goal-proof').trim()};if(!g.name)return;if(idx==='')a.goals.push(g);else a.goals[Number(idx)]=g;dtexStoreOverride(a,['goals']);dtexRecalc();renderDrawer(a);dtexRefresh();return}if(e.target.closest?.('[data-add-person],[data-del-person],[data-add-meeting],[data-del-meeting]'))setTimeout(()=>{dtexRecalc();renderKpis();renderWatch();renderAccounts();renderMatrix();renderRenewals();if(activeAccount)renderDrawer(activeAccount)},0)},false);
const dtexOldBoot=boot;boot=function(){dtexRecalc();dtexOldBoot();dtexRenderSettings()};
})();
</script>'''
